mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM documents
    WHERE id = #{id}
      AND user_id = #{userId}
      AND deleted_at IS NULL
)

SELECT EXISTS (
    SELECT 1
    FROM document_versions
    WHERE document_id = #{documentId}
      AND save_request_id = #{saveRequestId}
)

SELECT COALESCE(MAX(version_no), 0) + 1
FROM document_versions
WHERE document_id = #{documentId}
